sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    var valueOfShow = api.state.showDropDown;
    var button = valueOfShow? "Validate" : "Close";
    var valid = [{
        "id": 2,
        "label": "",
        "overflow": false,
        "color": "primary",
        "icon": "",
        "disabled": false,
        "type": "Button",
        "children": [{
            "id": valueOfShow,
            "label": button,
            "icon": "",
            "uxActionType": "UIAction",
            "action": {
                "name": "",
                "label": button,
                "color": "primary",
                "icon": "",
                "shouldBeInOverflow": false,
                "sysId": "",
                "clientScript": "function onClick(g_form) {\r\n\r\n}",
                "hint": null,
                "hasClientScript": false,
                "itemName": button,
                "id": valueOfShow,
                "uxActionType": "UIAction"
            },
            "disabled": false
        }]
    }];
    return valid;
}
